/**
 * Pixi Editor components.
 *
 * Generated by Pixi Editor. It is plain TypeScript: safe to read, edit and commit.
 * A component adds a reusable behaviour to any Pixi object:
 *
 *   addComponent(scoreText, Anchor, { h: "left", v: "top", x: 20, y: 18 });
 *   addComponent(playButton, Button, { hoverScale: 1.06 });
 *   playButton.on("pointertap", () => startGame());
 *
 * Components keep working without the editor. While Pixi Editor is in Edit mode,
 * animations pause so objects can be positioned precisely.
 */
import { Container, Ticker, type Application } from "pixi.js";

export abstract class Component<P extends object = object> {
  readonly target: Container;
  params: P;

  constructor(target: Container, params: P) {
    this.target = target;
    this.params = params;
  }

  /** Called once, right after the component is attached. */
  attach(): void {}
  /** Called every frame. */
  update(): void {}
  /** Called after `params` change (for example from Pixi Editor). */
  apply(): void {}
  /** Called when the component is removed. */
  detach(): void {}
}

export interface ComponentType<P extends object> {
  new (target: Container, params: P): Component<P>;
  readonly componentName: string;
  readonly defaults: P;
}

// Shared state lives on globalThis so every copy of this module sees the same components.
interface ComponentState {
  byTarget: WeakMap<Container, Component[]>;
  running: Set<Component>;
  ticking: boolean;
  app: Application | null;
}
const g = globalThis as typeof globalThis & {
  __PIXI_COMPONENTS__?: ComponentState;
  __PIXI_APP__?: Application;
  __PIXI_EDITOR__?: { paused?: boolean };
};
const state: ComponentState = (g.__PIXI_COMPONENTS__ ??= {
  byTarget: new WeakMap(),
  running: new Set(),
  ticking: false,
  app: null,
});

/** Tells components which Application to use for the screen size (needed by Anchor). */
export function useApp(app: Application): void {
  state.app = app;
}

/** Current screen size, or null before the Application is initialised. */
export function getScreen(): { width: number; height: number } | null {
  const app = state.app ?? g.__PIXI_APP__ ?? null;
  return app && app.renderer ? app.screen : null;
}

/** True while Pixi Editor is in Edit mode. Always false in the real game. */
export function isEditorPaused(): boolean {
  return !!g.__PIXI_EDITOR__?.paused;
}

function tick(): void {
  for (const component of state.running) {
    if (component.target.destroyed) {
      state.running.delete(component);
      continue;
    }
    component.update();
  }
}

function nameOf(component: Component): string {
  return (component.constructor as unknown as { componentName: string })
    .componentName;
}

/** Adds a component to `target` (replacing one of the same type) and returns it. */
export function addComponent<P extends object>(
  target: Container,
  type: ComponentType<P>,
  params: Partial<P> = {},
): Component<P> {
  removeComponent(target, type);
  const component = new type(target, { ...type.defaults, ...params });
  const list = state.byTarget.get(target) ?? [];
  list.push(component);
  state.byTarget.set(target, list);
  state.running.add(component);
  component.attach();
  component.apply();
  if (!state.ticking) {
    state.ticking = true;
    Ticker.shared.add(tick);
  }
  return component;
}

/** Returns the component of `type` on `target`, if any. */
export function getComponent<P extends object>(
  target: Container,
  type: ComponentType<P>,
): Component<P> | undefined {
  return (state.byTarget.get(target) ?? []).find(
    (c) => nameOf(c) === type.componentName,
  ) as Component<P> | undefined;
}

/** All components on `target`. */
export function getComponents(target: Container): readonly Component[] {
  return state.byTarget.get(target) ?? [];
}

/** Removes the component of `type` from `target`. */
export function removeComponent<P extends object>(
  target: Container,
  type: ComponentType<P>,
): void {
  const list = state.byTarget.get(target);
  if (!list) return;
  const index = list.findIndex((c) => nameOf(c) === type.componentName);
  if (index < 0) return;
  const [component] = list.splice(index, 1);
  state.running.delete(component);
  component.detach();
}

// ---------------------------------------------------------------- Anchor

export type HorizontalEdge = "left" | "center" | "right";
export type VerticalEdge = "top" | "middle" | "bottom";

export interface AnchorParams {
  /** Horizontal screen edge to stick to. */
  h: HorizontalEdge;
  /** Vertical screen edge to stick to. */
  v: VerticalEdge;
  /** Offset in pixels from the horizontal edge. */
  x: number;
  /** Offset in pixels from the vertical edge. */
  y: number;
}

/** Keeps an object at a fixed offset from a screen edge or corner, even when the screen resizes. */
export class Anchor extends Component<AnchorParams> {
  static readonly componentName = "Anchor";
  static readonly defaults: AnchorParams = { h: "left", v: "top", x: 0, y: 0 };

  update(): void {
    this.apply();
  }

  apply(): void {
    const screen = getScreen();
    const parent = this.target.parent;
    if (!screen || !parent) return;
    const { h, v, x, y } = this.params;
    const gx =
      (h === "left" ? 0 : h === "center" ? screen.width / 2 : screen.width) + x;
    const gy =
      (v === "top" ? 0 : v === "middle" ? screen.height / 2 : screen.height) +
      y;
    const local = parent.toLocal({ x: gx, y: gy });
    if (this.target.x !== local.x || this.target.y !== local.y)
      this.target.position.set(local.x, local.y);
  }

  /** Converts a local position into edge offsets (used by Pixi Editor when dragging). */
  setFromPosition(localX: number, localY: number): void {
    const screen = getScreen();
    const parent = this.target.parent;
    if (!screen || !parent) return;
    const global = parent.toGlobal({ x: localX, y: localY });
    const { h, v } = this.params;
    const ex =
      h === "left" ? 0 : h === "center" ? screen.width / 2 : screen.width;
    const ey =
      v === "top" ? 0 : v === "middle" ? screen.height / 2 : screen.height;
    this.params = {
      ...this.params,
      x: Math.round(global.x - ex),
      y: Math.round(global.y - ey),
    };
    this.apply();
  }
}

// ---------------------------------------------------------------- Button

export interface ButtonParams {
  /** Scale multiplier while the pointer is over the object. */
  hoverScale: number;
  /** Scale multiplier while the object is pressed. */
  pressScale: number;
  /** CSS cursor shown over the object. */
  cursor: string;
}

/**
 * Makes an object behave like a button: pointer cursor plus hover and press feedback.
 * Listen for clicks in your code with `target.on("pointertap", handler)`.
 */
export class Button extends Component<ButtonParams> {
  static readonly componentName = "Button";
  static readonly defaults: ButtonParams = {
    hoverScale: 1.05,
    pressScale: 0.95,
    cursor: "pointer",
  };

  private multiplier = 1;
  private hovered = false;
  private pressed = false;

  private readonly onOver = (): void => {
    this.hovered = true;
    this.refresh();
  };
  private readonly onOut = (): void => {
    this.hovered = false;
    this.pressed = false;
    this.refresh();
  };
  private readonly onDown = (): void => {
    this.pressed = true;
    this.refresh();
  };
  private readonly onUp = (): void => {
    this.pressed = false;
    this.refresh();
  };

  attach(): void {
    const t = this.target;
    t.eventMode = "static";
    t.on("pointerover", this.onOver);
    t.on("pointerout", this.onOut);
    t.on("pointerdown", this.onDown);
    t.on("pointerup", this.onUp);
    t.on("pointerupoutside", this.onUp);
  }

  apply(): void {
    this.target.cursor = this.params.cursor;
    this.refresh();
  }

  detach(): void {
    const t = this.target;
    t.off("pointerover", this.onOver);
    t.off("pointerout", this.onOut);
    t.off("pointerdown", this.onDown);
    t.off("pointerup", this.onUp);
    t.off("pointerupoutside", this.onUp);
    this.setMultiplier(1);
  }

  private refresh(): void {
    const { hoverScale, pressScale } = this.params;
    this.setMultiplier(
      this.pressed ? pressScale : this.hovered ? hoverScale : 1,
    );
  }

  private setMultiplier(next: number): void {
    const k = next / this.multiplier;
    if (k !== 1)
      this.target.scale.set(this.target.scale.x * k, this.target.scale.y * k);
    this.multiplier = next;
  }
}

// ---------------------------------------------------------------- Tween

export type TweenKind = "pulse" | "float" | "spin" | "fade";

export interface TweenParams {
  /** pulse = scale up and down, float = move up and down, spin = rotate, fade = blink. */
  kind: TweenKind;
  /** pulse: scale fraction, float: pixels, spin: turns per cycle, fade: alpha fraction. */
  amount: number;
  /** Cycles per second. */
  speed: number;
}

/** A looping idle animation, applied on top of the object's own values. */
export class Tween extends Component<TweenParams> {
  static readonly componentName = "Tween";
  static readonly defaults: TweenParams = {
    kind: "pulse",
    amount: 0.05,
    speed: 1,
  };

  private time = 0;
  private applied = { scale: 1, y: 0, rotation: 0, alpha: 1 };
  private written = { sx: NaN, y: NaN, rotation: NaN, alpha: NaN };

  update(): void {
    this.reset();
    if (isEditorPaused()) return;
    this.time += Ticker.shared.deltaMS / 1000;
    const { kind, amount, speed } = this.params;
    const phase = Math.sin(this.time * speed * Math.PI * 2);
    const t = this.target;
    if (kind === "pulse") {
      this.applied.scale = 1 + amount * phase;
      t.scale.set(
        t.scale.x * this.applied.scale,
        t.scale.y * this.applied.scale,
      );
    } else if (kind === "float") {
      this.applied.y = amount * phase;
      t.y += this.applied.y;
    } else if (kind === "spin") {
      this.applied.rotation =
        (this.time * speed * amount * Math.PI * 2) % (Math.PI * 2);
      t.rotation += this.applied.rotation;
    } else {
      this.applied.alpha = 1 - amount * (0.5 + 0.5 * phase);
      t.alpha *= this.applied.alpha;
    }
    this.written = {
      sx: t.scale.x,
      y: t.y,
      rotation: t.rotation,
      alpha: t.alpha,
    };
  }

  detach(): void {
    this.reset();
  }

  /** Removes last frame's offset, unless something else has set the value since. */
  private reset(): void {
    const t = this.target;
    const a = this.applied;
    if (a.scale !== 1 && t.scale.x === this.written.sx)
      t.scale.set(t.scale.x / a.scale, t.scale.y / a.scale);
    if (a.y !== 0 && t.y === this.written.y) t.y -= a.y;
    if (a.rotation !== 0 && t.rotation === this.written.rotation)
      t.rotation -= a.rotation;
    if (a.alpha !== 1 && t.alpha === this.written.alpha) t.alpha /= a.alpha;
    this.applied = { scale: 1, y: 0, rotation: 0, alpha: 1 };
  }
}

/** Every component type, by name (used by Pixi Editor). */
export const componentTypes = { Anchor, Button, Tween };
